/* ---------------- перевірка рівня ----------------
   По одному завданню на навичку (усі уроки a1–a14), у порядку підручника.
   t — тема для звіту. */
const T = { "a.fred": "Дроби", "a.fadd": "Дроби", "a.fmul": "Дроби", "a.dops": "Десяткові дроби", "a.prop": "Пропорції й відсотки", "a.pct": "Пропорції й відсотки",
  "a.nadd": "Від'ємні числа", "a.nsub": "Від'ємні числа", "a.nmul": "Від'ємні числа", "a.ord": "Порядок дій і дужки", "a.br": "Порядок дій і дужки",
  "a.eroot": "Рівняння", "a.esimple": "Рівняння", "a.elin1": "Рівняння", "a.elin2": "Рівняння", "a.ebr": "Рівняння", "a.espec": "Рівняння",
  "a.emodel": "Задачі рівнянням", "a.eword": "Задачі рівнянням", "a.xval": "Вирази", "a.xlike": "Вирази", "a.xdist": "Вирази",
  "a.pwval": "Степені", "a.pwprop": "Степені", "a.pwcalc": "Степені", "a.mstd": "Одночлени", "a.mmul": "Одночлени" };
const DI = [
  { part: "Дроби, відсотки, від'ємні числа", items: ["a.fred", "a.fadd", "a.fmul", "a.dops", "a.prop", "a.pct", "a.nadd", "a.nsub", "a.nmul", "a.ord", "a.br"] },
  { part: "Рівняння і задачі", items: [["a.eroot", { multi: 1 }], "a.esimple", "a.elin1", "a.elin2", "a.ebr", "a.espec", "a.emodel", "a.eword"] },
  { part: "Вирази, степені, одночлени", items: ["a.xval", ["a.xval", { t: "hard" }], "a.xlike", "a.xdist", ["a.pwval", { t: "minus" }], ["a.pwval", { t: "neg" }], "a.pwprop", "a.pwcalc", ["a.mstd", { t: "std" }], ["a.mstd", { t: "deg" }], "a.mmul"] }
];
const items = [];
DI.forEach((p, pi) => p.items.forEach(x => { const [skill, args] = Array.isArray(x) ? x : [x]; items.push(args ? { skill, t: T[skill], part: pi, args } : { skill, t: T[skill], part: pi }); }));
w("diag.json", { title: "Алгебра: перевірка рівня", parts: DI.map(p => p.part), items });
console.log("ok:", skills.length, "навичок,", lessons.length, "уроків");
